insert into public.sources (id, title, publisher, url, retrieved_on, rights_note, published) values ('world-bank-pink-sheet', 'World Bank Commodity Price Data (The Pink Sheet), monthly prices', 'World Bank', 'https://www.worldbank.org/en/research/commodity-markets', '2026-11-07', 'This public seed does not copy the Pink Sheet Brent column. The workbook cites Bloomberg, EIG, OPEC and the World Bank, and the license for that column is unconfirmed. General World Bank catalog terms are not treated as permission. No monthly prices are inserted.', true) on conflict (id) do update set title = excluded.title, publisher = excluded.publisher, url = excluded.url, retrieved_on = excluded.retrieved_on, rights_note = excluded.rights_note, published = true;
insert into public.sources (id, title, publisher, url, retrieved_on, rights_note, published) values ('ecb-ea-10y', 'Euro area 10-year government benchmark bond yield', 'European Central Bank', 'https://data-api.ecb.europa.eu/service/data/FM/M.U2.EUR.4F.BB.U2_10Y.YLD?format=csvdata&startPeriod=2014-01', '2026-11-07', 'This public seed does not copy series FM.M.U2.EUR.4F.BB.U2_10Y.YLD. The recorded source is ECB/FINANCIAL PROVIDERS, and the third-party exception is not closed. No monthly yields are inserted. Use the ECB Data Portal for the authoritative series.', true) on conflict (id) do update set title = excluded.title, publisher = excluded.publisher, url = excluded.url, retrieved_on = excluded.retrieved_on, rights_note = excluded.rights_note, published = true;
